  1→/**
  2→ * Centralized Postmark email service.
  3→ *
  4→ * All send functions return `true` on success, `false` on failure — they never
  5→ * throw. This lets callers fire-and-forget without wrapping in try/catch.
  6→ */
  7→import { ServerClient } from "postmark";
  8→
  9→// ---------------------------------------------------------------------------
 10→// Client singleton
 11→// ---------------------------------------------------------------------------
 12→
 13→let client: ServerClient | null = null;
 14→
 15→function getClient(): ServerClient | null {
 16→  if (client) return client;
 17→  const apiKey = process.env.POSTMARK_API_KEY;
 18→  if (!apiKey) {
 19→    console.warn("[email] POSTMARK_API_KEY not set — emails will be skipped");
 20→    return null;
 21→  }
 22→  client = new ServerClient(apiKey);
 23→  return client;
 24→}
 25→
 26→function getFromEmail(): string {
 27→  return process.env.POSTMARK_FROM_EMAIL || "noreply@example.com";
 28→}
 29→
 30→function shopDisplayName(shop: string): string {
 31→  return shop.replace(".myshopify.com", "");
 32→}
 33→
 34→// ---------------------------------------------------------------------------
 35→// 1. Waitlist Confirmation  (App → Customer)
 36→// ---------------------------------------------------------------------------
 37→
 38→export async function sendWaitlistConfirmation(
 39→  to: string,
 40→  zipCode: string,
 41→  shop: string,
 42→): Promise<boolean> {
 43→  const pm = getClient();
 44→  if (!pm) return false;
 45→
 46→  const name = shopDisplayName(shop);
 47→
 48→  try {
 49→    await pm.sendEmail({
 50→      From: getFromEmail(),
 51→      To: to,
 52→      Subject: `You're on the waitlist — ${name}`,
 53→      HtmlBody: `
 54→        <div style="font-family:Arial,sans-serif;max-width:560px;margin:0 auto;padding:24px">
 55→          <h2 style="margin:0 0 16px">You're on the waitlist!</h2>
 56→          <p>Thanks for signing up. We'll let you know as soon as delivery is available to <strong>${zipCode}</strong>.</p>
 57→          <p style="color:#666;font-size:13px;margin-top:24px">— ${name}</p>
 58→        </div>
 59→      `,
 60→      TextBody: `You're on the waitlist!\n\nThanks for signing up. We'll let you know as soon as delivery is available to ${zipCode}.\n\n— ${name}`,
 61→      MessageStream: "outbound",
 62→    });
 63→    return true;
 64→  } catch (error) {
 65→    console.error("[email] Failed to send waitlist confirmation:", error);
 66→    return false;
 67→  }
 68→}
 69→
