 31→// ---------------------------------------------------------------------------
 32→// Loader
 33→// ---------------------------------------------------------------------------
 34→
 35→export const loader = async ({ request }: LoaderFunctionArgs) => {
 36→  const { session } = await authenticate.admin(request);
 37→  const shop = session.shop;
 38→
 39→  const [subscription, zipCount, shopSettings] = await Promise.all([
 40→    getShopSubscription(shop),
 41→    db.zipCode.count({ where: { shop } }),
 42→    db.shopSettings.findUnique({ where: { shop } }),
 43→  ]);
 44→
 45→  return {
 46→    subscription,
 47→    zipCount,
 48→    shop,
 49→    defaultBehavior: shopSettings?.defaultBehavior ?? "block",
 50→    notificationEmail: shopSettings?.notificationEmail ?? "",
 51→  };
 52→};
 53→
 54→// ---------------------------------------------------------------------------
 55→// Action
 56→// ---------------------------------------------------------------------------
 57→
 58→export const action = async ({ request }: ActionFunctionArgs) => {
 59→  const { session } = await authenticate.admin(request);
 60→  const shop = session.shop;
 61→
 62→  const formData = await request.formData();
 63→  const intent = formData.get("intent") as string;
 64→
 65→  try {
 66→    if (intent === "save-behavior") {
 67→      const defaultBehavior = formData.get("defaultBehavior") as string;
 68→      if (defaultBehavior !== "block" && defaultBehavior !== "allow") {
 69→        return { error: "Invalid value for defaultBehavior" };
 70→      }
 71→      await db.shopSettings.upsert({
 72→        where: { shop },
 73→        create: { shop, defaultBehavior },
 74→        update: { defaultBehavior },
 75→      });
 76→      return { success: true, intent };
 77→    }
 78→
 79→    if (intent === "save-notification") {
 80→      const notificationEmail =
 81→        (formData.get("notificationEmail") as string | null) ?? "";
 82→      await db.shopSettings.upsert({
 83→        where: { shop },
 84→        create: { shop, notificationEmail: notificationEmail || null },
 85→        update: { notificationEmail: notificationEmail || null },
 86→      });
 87→      return { success: true, intent };
 88→    }
 89→
 90→    if (intent === "send-test-email") {
 91→      const testEmail = (formData.get("testEmail") as string | null) ?? "";
 92→      if (!testEmail) return { error: "No email address provided." };
 93→      const sent = await sendTestEmail(testEmail);
 94→      return sent
 95→        ? { success: true, intent }
 96→        : { error: "Failed to send test email. Check your Postmark API key and sender email." };
 97→    }
 98→
 99→    return { error: "Unknown intent" };
100→  } catch {
101→    return { error: "Failed to save settings. Please try again." };
102→  }
103→};
104→
105→// ---------------------------------------------------------------------------
106→// Component
107→// ---------------------------------------------------------------------------
108→
109→export default function SettingsPage() {
110→  const { subscription, zipCount, shop, defaultBehavior, notificationEmail } =
111→    useLoaderData<typeof loader>();
112→  const navigate = useNavigate();
113→  const shopify = useAppBridge();
114→  const limits = PLAN_LIMITS[subscription.planTier];
115→
116→  // Fetchers — one per save section so loading states stay independent
117→  const behaviorFetcher = useFetcher<typeof action>();
118→  const notificationFetcher = useFetcher<typeof action>();
119→  const testEmailFetcher = useFetcher<typeof action>();
120→
121→  // Local controlled state
122→  const [behaviorValue, setBehaviorValue] = useState(defaultBehavior);
123→  const [emailValue, setEmailValue] = useState(notificationEmail);
124→
125→  const isSavingBehavior = behaviorFetcher.state !== "idle";
126→  const isSavingNotification = notificationFetcher.state !== "idle";
127→  const isSaving = isSavingBehavior || isSavingNotification;
128→
129→  // Track dirty state
130→  const isDirty =
131→    behaviorValue !== defaultBehavior || emailValue !== notificationEmail;
132→
133→  // Toast on success
134→  useEffect(() => {
135→    if (
136→      behaviorFetcher.data &&
137→      "success" in behaviorFetcher.data &&
138→      behaviorFetcher.data.success
139→    ) {
140→      shopify.toast.show("Settings saved");
141→    }
142→  }, [behaviorFetcher.data, shopify]);
143→
144→  useEffect(() => {
145→    if (
146→      notificationFetcher.data &&
147→      "success" in notificationFetcher.data &&
148→      notificationFetcher.data.success
149→    ) {
150→      shopify.toast.show("Settings saved");
151→    }
152→  }, [notificationFetcher.data, shopify]);
153→
154→  useEffect(() => {
155→    if (
156→      testEmailFetcher.data &&
157→      "success" in testEmailFetcher.data &&
158→      testEmailFetcher.data.success
159→    ) {
160→      shopify.toast.show("Test email sent!");
161→    }
162→  }, [testEmailFetcher.data, shopify]);
163→
164→  const handleBehaviorChange = useCallback(
165→    (value: string) => setBehaviorValue(value),
166→    [],
167→  );
168→
169→  const handleEmailChange = useCallback(
170→    (value: string) => setEmailValue(value),
171→    [],
172→  );
173→
174→  const handleSaveAll = useCallback(() => {
175→    if (behaviorValue !== defaultBehavior) {
176→      const fd = new FormData();
177→      fd.append("intent", "save-behavior");
178→      fd.append("defaultBehavior", behaviorValue);
179→      behaviorFetcher.submit(fd, { method: "post" });
180→    }
181→    if (emailValue !== notificationEmail) {
182→      const fd = new FormData();
183→      fd.append("intent", "save-notification");
184→      fd.append("notificationEmail", emailValue);
185→      notificationFetcher.submit(fd, { method: "post" });
186→    }
187→  }, [behaviorFetcher, notificationFetcher, behaviorValue, emailValue, defaultBehavior, notificationEmail]);
188→
189→  const handleDiscard = useCallback(() => {
190→    setBehaviorValue(defaultBehavior);
191→    setEmailValue(notificationEmail);
192→  }, [defaultBehavior, notificationEmail]);
193→
194→  const handleSendTestEmail = useCallback(() => {
195→    if (!emailValue) return;
196→    const fd = new FormData();
197→    fd.append("intent", "send-test-email");
198→    fd.append("testEmail", emailValue);
199→    testEmailFetcher.submit(fd, { method: "post" });
200→  }, [emailValue, testEmailFetcher]);
201→
202→  const behaviorOptions = [
203→    {
204→      label: "Block — show 'not available' message (recommended)",
205→      value: "block",
206→    },
207→    {
208→      label: "Allow — treat as available (for stores with broad coverage)",
209→      value: "allow",
210→    },
211→  ];
212→
213→  const planBadgeTone =
214→    subscription.planTier === "ultimate"
215→      ? ("success" as const)
216→      : subscription.planTier === "pro"
217→        ? ("info" as const)
218→        : subscription.planTier === "starter"
219→          ? ("attention" as const)
220→          : ("new" as const);
221→
222→  const planLabel = limits.label;
223→
224→  return (
225→    <Page
226→      title="Settings"
227→      subtitle="Manage your app settings and subscription"
228→      backAction={{ onAction: () => navigate("/app") }}
229→      primaryAction={isDirty ? {
230→        content: "Save",
231→        onAction: handleSaveAll,
232→        loading: isSaving,
233→      } : undefined}
234→      secondaryActions={isDirty ? [{
235→        content: "Discard",
236→        onAction: handleDiscard,
237→      }] : []}
238→    >
239→      <Box paddingBlockEnd="1600">
240→        <Layout>
241→
242→          {/* ----------------------------------------------------------------
243→              Section 1: Subscription
244→          ---------------------------------------------------------------- */}
245→          <Layout.Section>
246→            <Card>
247→              <BlockStack gap="400">
248→                <Text as="h2" variant="headingMd">
249→                  Subscription
250→                </Text>
251→                <Divider />
252→                <InlineStack align="space-between" blockAlign="center">
253→                  <BlockStack gap="100">
254→                    <Text as="p" variant="bodyMd">
255→                      Current Plan
256→                    </Text>
257→                    <InlineStack gap="200" blockAlign="center">
258→                      <Badge tone={planBadgeTone}>{`${planLabel} Plan`}</Badge>
259→                      {subscription.planTier !== "free" && (
260→                        <Text as="span" tone="subdued" variant="bodySm">
261→                          {subscription.billingInterval === "annual"
262→                            ? "Billed annually"
263→                            : "Billed monthly"}
264→                        </Text>
265→                      )}
266→                      {(subscription.planTier === "free" || subscription.planTier === "starter") && (
267→                        <Text as="span" tone="subdued" variant="bodySm">
268→                          {subscription.planTier === "free" ? "Limited features" : "Essential features"}
269→                        </Text>
270→                      )}
271→                    </InlineStack>
272→                  </BlockStack>
273→                  <Button
274→                    variant="primary"
275→                    onClick={() => navigate("/app/pricing")}
276→                  >
277→                    {subscription.planTier === "free" || subscription.planTier === "starter"
278→                      ? "Upgrade Plan"
279→                      : "Manage Plan"}
280→                  </Button>
281→                </InlineStack>
282→              </BlockStack>
283→            </Card>
284→          </Layout.Section>
285→
286→          {/* ----------------------------------------------------------------
287→              Section 2: Default Behavior for Unknown Zip Codes (NEW)
288→          ---------------------------------------------------------------- */}
289→          <Layout.Section>
290→            <Card>
291→              <BlockStack gap="400">
292→                <BlockStack gap="100">
293→                  <Text as="h2" variant="headingMd">
294→                    Default Behavior for Unknown Zip Codes
295→                  </Text>
296→                  <Text as="p" tone="subdued" variant="bodyMd">
297→                    Choose what happens when a customer enters a zip code that
298→                    is not in your list.
299→                  </Text>
300→                </BlockStack>
301→                <Divider />
302→                {behaviorFetcher.data &&
303→                  "error" in behaviorFetcher.data &&
304→                  behaviorFetcher.data.error && (
305→                    <Banner tone="critical">
306→                      {behaviorFetcher.data.error}
307→                    </Banner>
308→                  )}
309→                <Select
310→                  label="Behavior for unlisted zip codes"
311→                  options={behaviorOptions}
312→                  value={behaviorValue}
313→                  onChange={handleBehaviorChange}
314→                />
315→                <Text as="p" tone="subdued" variant="bodySm">
316→                  This only applies to zip codes not in your list. Explicitly
