328→              <BlockStack gap="400">
329→                <BlockStack gap="100">
330→                  <Text as="h2" variant="headingMd">
331→                    Waitlist Notifications
332→                  </Text>
333→                  <Text as="p" tone="subdued" variant="bodyMd">
