  1→/**
  2→ * Public API endpoint — joins a customer to the waitlist from the storefront widget.
  3→ *
  4→ * Called from the theme app extension block when a zip code check fails and
  5→ * the merchant has enabled the waitlist feature.
  6→ *
  7→ * POST /api/waitlist
  8→ * Body: { shop: string, zip: string, email: string }
  9→ *
 10→ * Response:
 11→ *   200 { success: true, message: "..." }
 12→ *   400 { error: "..." }
 13→ *   500 { error: "..." }
 14→ */
 15→import type { ActionFunctionArgs, LoaderFunctionArgs } from "react-router";
 16→import db from "../db.server";
 17→import { getShopSubscription } from "../billing.server";
 18→import { UNLIMITED } from "../plans";
 19→import { normalizeZipCode } from "../utils/zip";
 20→import {
 21→  sendWaitlistConfirmation,
 22→  sendMerchantWaitlistAlert,
 23→} from "../email.server";
 24→
 25→const CORS_HEADERS = {
 26→  "Access-Control-Allow-Origin": "*",
 27→  "Access-Control-Allow-Methods": "POST, OPTIONS",
 28→  "Access-Control-Allow-Headers": "Content-Type",
 29→  "Content-Type": "application/json",
 30→};
 31→
 32→// Handle CORS preflight
 33→export const loader = async ({ request }: LoaderFunctionArgs) => {
 34→  if (request.method === "OPTIONS") {
 35→    return new Response(null, { status: 204, headers: CORS_HEADERS });
 36→  }
 37→  return new Response(JSON.stringify({ error: "Method not allowed" }), {
 38→    status: 405,
 39→    headers: CORS_HEADERS,
 40→  });
 41→};
 42→
 43→export const action = async ({ request }: ActionFunctionArgs) => {
 44→  if (request.method === "OPTIONS") {
 45→    return new Response(null, { status: 204, headers: CORS_HEADERS });
 46→  }
 47→
 48→  if (request.method !== "POST") {
 49→    return new Response(JSON.stringify({ error: "Method not allowed" }), {
 50→      status: 405,
 51→      headers: CORS_HEADERS,
 52→    });
 53→  }
 54→
 55→  let shop: string | null = null;
 56→  let zip: string | null = null;
 57→  let email: string | null = null;
 58→  let name: string | null = null;
 59→
 60→  try {
 61→    const body = await request.json();
 62→    shop = body?.shop ?? null;
 63→    zip = body?.zip ?? null;
 64→    email = body?.email ?? null;
 65→    name = body?.name ?? null;
 66→  } catch {
 67→    return new Response(JSON.stringify({ error: "Invalid JSON body" }), {
 68→      status: 400,
 69→      headers: CORS_HEADERS,
 70→    });
 71→  }
 72→
 73→  if (!shop || !zip || !email) {
 74→    return new Response(
 75→      JSON.stringify({ error: "Missing required fields: shop, zip, email" }),
 76→      { status: 400, headers: CORS_HEADERS },
 77→    );
 78→  }
 79→
 80→  // Validate shop is a real myshopify.com domain (prevents cross-shop enumeration)
 81→  if (!/^[a-zA-Z0-9][a-zA-Z0-9-]*\.myshopify\.com$/.test(shop) || shop.length > 100) {
 82→    return new Response(
 83→      JSON.stringify({ error: "Invalid shop parameter" }),
 84→      { status: 400, headers: CORS_HEADERS },
 85→    );
 86→  }
 87→
 88→  // Enforce input length limits to prevent abuse
 89→  if (zip.length > 20 || email.length > 254) {
 90→    return new Response(
 91→      JSON.stringify({ error: "Invalid input" }),
 92→      { status: 400, headers: CORS_HEADERS },
 93→    );
 94→  }
 95→
 96→  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
 97→    return new Response(
 98→      JSON.stringify({ error: "Invalid email address" }),
 99→      { status: 400, headers: CORS_HEADERS },
100→    );
101→  }
102→
103→  // Check if shop's plan allows waitlist
104→  try {
105→    const subscription = await getShopSubscription(shop);
106→    if (subscription.limits.maxWaitlist === 0) {
107→      return new Response(
108→        JSON.stringify({ error: "Waitlist is not available on this store's plan" }),
109→        { status: 400, headers: CORS_HEADERS },
110→      );
111→    }
112→    // Enforce entry limit for Starter plan
113→    if (subscription.limits.maxWaitlist < UNLIMITED) {
114→      const currentCount = await db.waitlistEntry.count({ where: { shop } });
115→      if (currentCount >= subscription.limits.maxWaitlist) {
116→        return new Response(
117→          JSON.stringify({ error: "Waitlist is currently full. Please try again later." }),
118→          { status: 400, headers: CORS_HEADERS },
119→        );
120→      }
121→    }
122→  } catch {
123→    // If subscription check fails, deny the request to prevent plan bypass
124→    return new Response(
125→      JSON.stringify({ error: "Unable to verify subscription. Please try again later." }),
126→      { status: 503, headers: CORS_HEADERS },
127→    );
128→  }
129→
130→  try {
131→    const normalizedZip = normalizeZipCode(zip);
132→
133→    await db.waitlistEntry.upsert({
134→      where: {
135→        shop_email_zipCode: {
136→          shop,
137→          email,
138→          zipCode: normalizedZip,
139→        },
140→      },
141→      create: {
142→        shop,
143→        email,
144→        name: name ? name.trim().substring(0, 100) : null,
145→        zipCode: normalizedZip,
146→        status: "waiting",
147→      },
148→      update: {
149→        status: "waiting",
150→      },
151→    });
152→
153→    // Fire-and-forget: send confirmation to customer
154→    sendWaitlistConfirmation(email, normalizedZip, shop).catch(() => {});
155→
156→    // Fire-and-forget: notify merchant if notificationEmail is set
157→    db.shopSettings
158→      .findUnique({ where: { shop }, select: { notificationEmail: true } })
159→      .then((settings) => {
160→        if (settings?.notificationEmail) {
161→          sendMerchantWaitlistAlert(
162→            settings.notificationEmail,
163→            email,
164→            normalizedZip,
165→            shop,
166→          ).catch(() => {});
167→        }
168→      })
169→      .catch(() => {});
170→
171→    return new Response(
172→      JSON.stringify({
173→        success: true,
174→        message: "You've been added to the waitlist!",
175→      }),
176→      { status: 200, headers: CORS_HEADERS },
177→    );
178→  } catch {
179→    return new Response(
180→      JSON.stringify({ error: "Failed to join waitlist. Please try again." }),
181→      { status: 500, headers: CORS_HEADERS },
182→    );
183→  }
184→};
